export default ["-- =====================================================================\n-- STEP 88. Career > Brainteasers. Safe to run twice.\n-- ---------------------------------------------------------------------\n-- 1. public.brainteasers: the questions, their type, the firms they are\n--    attributed to and their worked solutions. Loaded once from the\n--    starter set in supabase/functions/career-brainteasers/seed.ts the\n--    first time the page is opened, then corrected and added to in the\n--    page itself.\n-- 2. public.brainteaser_progress: each member's own training record, one\n--    row per question they have touched: whether they solved it on their\n--    own or needed the solution, a personal \"hard\" flag, a private note,\n--    and when they first opened the solution.\n-- 3. The greenbook: one PDF in Career, kept in its own private bucket\n--    (career-library, 60 MB) and listed in career_files as kind\n--    'greenbook'. Only the President and the admin account replace it;\n--    every download is a copy watermarked with the reader's name, and is\n--    recorded in public.greenbook_downloads.\n--\n-- NOTHING HERE IS READABLE FROM THE BROWSER. All three tables have RLS on\n-- and no policy, and are revoked from anon and authenticated: the\n-- career-brainteasers function (service role) is the only way in, which\n-- is what lets it hand a solution out one at a time, never the whole set.\n-- =====================================================================\n\n-- \u2500\u2500 1. The questions \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nCREATE TABLE IF NOT EXISTS public.brainteasers (\n  id          text PRIMARY KEY CHECK (id ~ '^[a-z0-9][a-z0-9-]{0,79}$'),\n  title       text NOT NULL CHECK (char_length(btrim(title)) BETWEEN 1 AND 120),\n  field       text NOT NULL CHECK (char_length(btrim(field)) BETWEEN 1 AND 40),\n  firms       text[] NOT NULL DEFAULT '{}'::text[] CHECK (cardinality(firms) <= 30),\n  question    text NOT NULL CHECK (char_length(question) BETWEEN 1 AND 8000),\n  answer      text NOT NULL CHECK (char_length(answer) BETWEEN 1 AND 20000),\n  sort_order  integer NOT NULL DEFAULT 0,\n  hidden      boolean NOT NULL DEFAULT false,\n  created_by  uuid REFERENCES auth.users(id) ON DELETE SET NULL,\n  updated_by  uuid REFERENCES auth.users(id) ON DELETE SET NULL,\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  updated_at  timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS brainteasers_order ON public.brainteasers (sort_order, id);\nALTER TABLE public.brainteasers ENABLE ROW LEVEL SECURITY;\nREVOKE ALL ON public.brainteasers FROM PUBLIC, anon, authenticated;\nGRANT ALL ON public.brainteasers TO service_role;\nDROP TRIGGER IF EXISTS update_brainteasers_updated_at ON public.brainteasers;\nCREATE TRIGGER update_brainteasers_updated_at BEFORE UPDATE ON public.brainteasers\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\n-- \u2500\u2500 2. Each member's training record \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nCREATE TABLE IF NOT EXISTS public.brainteaser_progress (\n  user_id      uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  problem_id   text NOT NULL REFERENCES public.brainteasers(id) ON DELETE CASCADE ON UPDATE CASCADE,\n  status       text CHECK (status IS NULL OR status IN ('solved', 'needed_help')),\n  flagged      boolean NOT NULL DEFAULT false,\n  note         text CHECK (note IS NULL OR char_length(note) <= 2000),\n  revealed_at  timestamptz,\n  status_at    timestamptz,\n  updated_at   timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (user_id, problem_id)\n);\nCREATE INDEX IF NOT EXISTS brainteaser_progress_reveals ON public.brainteaser_progress (user_id, revealed_at);\nALTER TABLE public.brainteaser_progress ENABLE ROW LEVEL SECURITY;\nREVOKE ALL ON public.brainteaser_progress FROM PUBLIC, anon, authenticated;\nGRANT ALL ON public.brainteaser_progress TO service_role;\n\n-- \u2500\u2500 3. The greenbook \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nALTER TABLE public.career_files DROP CONSTRAINT IF EXISTS career_files_kind_check;\nALTER TABLE public.career_files ADD CONSTRAINT career_files_kind_check\n  CHECK (kind IN ('cv_template', 'cl_template', 'portrait_background', 'wallpaper', 'greenbook'));\n\nINSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nVALUES ('career-library', 'career-library', false, 62914560, ARRAY['application/pdf'])\nON CONFLICT (id) DO UPDATE\n   SET public = false, file_size_limit = 62914560, allowed_mime_types = ARRAY['application/pdf'];\n\nCREATE TABLE IF NOT EXISTS public.greenbook_downloads (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id       uuid REFERENCES auth.users(id) ON DELETE SET NULL,\n  name          text NOT NULL,\n  email         text,\n  file_id       uuid,\n  downloaded_at timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS greenbook_downloads_user ON public.greenbook_downloads (user_id, downloaded_at DESC);\nCREATE INDEX IF NOT EXISTS greenbook_downloads_when ON public.greenbook_downloads (downloaded_at DESC);\nALTER TABLE public.greenbook_downloads ENABLE ROW LEVEL SECURITY;\nREVOKE ALL ON public.greenbook_downloads FROM PUBLIC, anon, authenticated;\nGRANT ALL ON public.greenbook_downloads TO service_role;\n", "-- =====================================================================\n-- STEP 88, corrections to the starter set of Career > Brainteasers.\n-- Safe to run twice, and safe on a database where the set is not loaded.\n-- ---------------------------------------------------------------------\n-- The page loads the starter set (career-brainteasers/seed.ts) the first\n-- time it is opened. This step corrects 60 of those questions:\n--   * seven behavioural questions had no question text, which the table\n--     refuses: the set could not finish loading (the question is now the\n--     title, e.g. \"Why do you want to become a Trader?\");\n--   * a category word left above some questions (\"Statistics\", \"Math\",\n--     \"Reasoning\") is removed;\n--   * formulas written as plain text (2^3, p_3, 1/8 * 1/8, C(9, 3),\n--     10^\\text{th}) are now typeset, and one calculation that had lost its\n--     multiplication signs ((987) / (321)) reads 9.8.7 / 3.2.1 again;\n--   * a few characters many fonts lack are replaced.\n--\n-- WHERE THE SET IS ALREADY LOADED, ONLY UNTOUCHED ROWS CHANGE: a row is\n-- updated only if nobody has edited it in the page (updated_by IS NULL)\n-- and its text is still exactly the original. Members' progress is kept.\n-- Where the set is not loaded yet, nothing happens here: the page loads\n-- the corrected set itself. Questions missing from a load that was cut\n-- short are added by the page on its next opening.\n-- =====================================================================\n\nUPDATE public.brainteasers SET answer = $bt$We begin with all 500 light bulbs switched on. The process then involves switching the state of each light bulb for every factor of its corresponding number. A light bulb's state is thus switched once for every unique factor of its number. The crucial observation here is that a bulb with an even number of factors will end up in its original state (on), as it undergoes an even number of switches. Conversely, bulbs with an odd number of factors will end up in the opposite state (off), due to experiencing an odd number of state switches.\n\nWith this understanding, the problem transforms into identifying how many numbers between 1 and 500 have an even number of factors (i.e., are not perfect squares), as these will be the bulbs that remain on.\n\nNumbers that are perfect squares are the exception in this case as they have an odd number of factors, including the square root that cannot be paired. For instance, the number 16 has factors 1, 2, 4, 8, and 16. As such, bulbs with perfect square numbers will end up switched off after the process.\n\nThe highest perfect square less than or equal to 500 is $22^2 = 484$, so there are 22 perfect squares in this range ($1^2, 2^2, \\ldots, 22^2$). These 22 bulbs will be switched off. Consequently, the remaining bulbs, 500 total bulbs minus the 22 perfect square bulbs, will stay on. Therefore, at the end of the process, 478 bulbs remain switched on.$bt$\n WHERE id = 'lightbulbs' AND updated_by IS NULL AND md5(question) = '0e6a2de139b37a7a2e63af98526f05cf' AND md5(answer) = '0628751be07c809ce9d9a35d4a1dc375';\nUPDATE public.brainteasers SET answer = $bt$After the first draw: 2 red, 3 black remain (5 cards total).\n\nKey observation: the color that does not run out first must appear last in the sequence.\n\nSo \"red runs out first\" $\\iff$ \"the final card is black\".\n\nEach of the 5 remaining cards is equally likely to be the last card because every permutation of the 5-card order is equally probable.\n\nNumber of favorable last cards = 3 (the blacks).\n\n$$\n\\Pr(\\text{last card is black}) = \\frac{3}{5}\n$$\n\nTherefore, the probability that the red pile is exhausted before the black pile is\n\n$$\n\\boxed{\\tfrac{3}{5}}\n$$$bt$\n WHERE id = 'last-card-standing' AND updated_by IS NULL AND md5(question) = 'd75cadf0a118df45ea5070bf1e3a5986' AND md5(answer) = '2e9766c3aba0c327758c482cfec7b9af';\nUPDATE public.brainteasers SET question = $bt$You are invited to partake in a challenge with an 8-sided die. Here's the setup:\n\n- Roll the die once.\n\n- Decide whether to accept that score or risk a second roll.\n\n- If you choose to roll again, your score is the combined total of both rolls.\n\n- If the sum exceeds 8, you \"bust\" and score zero.\n\nGiven these rules, outline the optimal strategy after the outcome of the first roll. Specifically, should you risk a second roll or keep your initial score?$bt$\n WHERE id = '8-sided-die' AND updated_by IS NULL AND md5(question) = '38535d2dbd7aed3c18e2f2eebde5c98d' AND md5(answer) = '82a28afe6f3f53c1628e62de9d007b0f';\nUPDATE public.brainteasers SET answer = $bt$1. Understanding the Problem Setup:\n\n- We have a fish of length $L$. The fish is divided into two equal parts by its midpoint.\n\n- Alex selects two points: one in the left half (0 to $\\frac{L}{2}$) and one in the right half ($\\frac{L}{2}$ to $L$). These points are denoted as $X$ and $Y$, respectively.\n\n- The goal is to find the probability that the distance between $X$ and $Y$ exceeds $\\frac{L}{3}$.\n\n2. Graphical Representation:\n\n- Imagine plotting this scenario on a coordinate plane. We create a square grid by subtracting $\\frac{L}{2}$ from the $Y$-coordinate so that the x-axis represents the position of $X$ (ranging from 0 to $\\frac{L}{2}$) and the new y-axis represents $Y - \\frac{L}{2}$ (also ranging from 0 to $\\frac{L}{2}$).\n\n- The grid is a square of size $\\frac{L}{2} \\times \\frac{L}{2}$ representing all possible outcomes.\n\n3. Identifying Areas on the Grid:\n\n- Within this square, the condition that $|X - Y| > \\frac{L}{3}$ (the distance between the points is greater than $\\frac{L}{3}$) corresponds to the region outside of a specific triangle.\n\n- This \u201cbad\u201d region (where the distance is less than or equal to $\\frac{L}{3}$) is a right triangle with vertices at $\\left(\\frac{L}{6}, 0\\right)$, $\\left(\\frac{L}{2}, 0\\right)$, and $\\left(\\frac{L}{2}, \\frac{L}{3}\\right)$.\n\n4. Calculating Areas:\n\n- The area of the triangle represents the outcomes where the distance between $X$ and $Y$ is less than or equal to $\\frac{L}{3}$. This area is $\\frac{1}{2} \\times \\frac{L}{3} \\times \\frac{L}{3} = \\frac{L^2}{18}$.\n\n- The total area of the square, representing all possible outcomes, is $\\left(\\frac{L}{2}\\right)^2 = \\frac{L^2}{4}$.\n\n5. Determining the Probability:\n\n- The probability that the distance between $X$ and $Y$ is greater than $\\frac{L}{3}$ is the proportion of the area outside the triangle to the total area of the square.\n\n- This probability is calculated as\n\n$$\n\\begin{aligned} P\\left[|X - Y| > \\tfrac{L}{3}\\right] &= \\frac{\\text{Area of square} - \\text{Area of triangle}}{\\text{Area of square}} \\\\ &= \\frac{\\left(\\frac{L}{2}\\right)^2 - \\frac{L^2}{18}}{\\left(\\frac{L}{2}\\right)^2} = \\frac{7}{9}. \\end{aligned}\n$$\n\nThe probability that the distance between the two randomly selected cutting points on the Peacock Bass is greater than $\\frac{L}{3}$ is $\\frac{7}{9}$.$bt$\n WHERE id = 'alex-s-fish' AND updated_by IS NULL AND md5(question) = '3322a8218f2108b33cf206cf2b3545c8' AND md5(answer) = 'e86f29b5ac3d757cf7efcfa7f49449de';\nUPDATE public.brainteasers SET answer = $bt$Let's find the probability that Alice and Bob record a different number of heads. There are $2^3 = 8$ possible outcomes for each of them when tossing the coin three times. Let's denote heads as H and tails as T. The possible outcomes are:\n\nHHH\n\nHHT\n\nHTH\n\nTHH\n\nHTT\n\nTHT\n\nTTH\n\nTTT\n\nNow, let's calculate the probability of them having the same number of heads:\n\nBoth get 0 heads: only 1 outcome (TTT) for each, so the probability is $\\frac{1}{8} \\times \\frac{1}{8} = \\frac{1}{64}$.\n\nBoth get 1 head: there are 3 outcomes (HTT, THT, TTH) for each, so the probability is $\\frac{3}{8} \\times \\frac{3}{8} = \\frac{9}{64}$.\n\nBoth get 2 heads: there are 3 outcomes (HHT, HTH, THH) for each, so the probability is $\\frac{3}{8} \\times \\frac{3}{8} = \\frac{9}{64}$.\n\nBoth get 3 heads: only 1 outcome (HHH) for each, so the probability is $\\frac{1}{8} \\times \\frac{1}{8} = \\frac{1}{64}$.\n\nSumming these probabilities, we get: $\\frac{1}{64} + \\frac{9}{64} + \\frac{9}{64} + \\frac{1}{64} = \\frac{20}{64}$.\n\nNow, to find the probability of them having a different number of heads, we can subtract this probability from 1 (since the total probability of all outcomes is 1): $1 - \\frac{20}{64} = \\frac{44}{64}$. Reducing the fraction gives us $\\frac{11}{16}$.\n\nThus, the probability of Alice and Bob having a different number of heads is $\\frac{11}{16}$, and the sum $M + N = 11 + 16 = 27$.$bt$\n WHERE id = 'bob-and-alice-toss-coins' AND updated_by IS NULL AND md5(question) = '85849495d2e2610831361e85504bbcce' AND md5(answer) = '0fd047cc13e8f1634d8229a8fbcfe61e';\nUPDATE public.brainteasers SET question = $bt$Given $W_t$ as a standard Brownian Motion, find the probability $P[W_1 > 0, W_2 > 0]$.$bt$\n WHERE id = 'brownian-motion-i' AND updated_by IS NULL AND md5(question) = '8c548f079dfe54cf1392229f91d54935' AND md5(answer) = '0e91215933d4d6e32a678414e6a063ea';\nUPDATE public.brainteasers SET question = $bt$Given the joint probability density function (pdf) defined as:\n\n$$\nf_{X_1, X_2}(x_1, x_2) = \\begin{cases} c(1-x_2) & \\text{if } 0 \\leq x_1 \\leq x_2 \\leq 1 \\\\0 & \\text{otherwise}\\end{cases}\n$$\n\nwhere $c$ is a constant ensuring $f_{X_1, X_2}$ is a valid joint pdf. Compute $E[X_1]$, the expected value of $X_1$.$bt$\n WHERE id = 'calculating-expectation' AND updated_by IS NULL AND md5(question) = 'b9c20e79b370e6471efd41bb85a613ad' AND md5(answer) = 'a90ca7fd2fc376d55962f49a8a79220a';\nUPDATE public.brainteasers SET question = $bt$In a standard deck of 52 cards, let's represent the cards from Ace to King as numbers from 1 to 13, respectively. If you were to draw a single card, what would be the expected value of that card? Furthermore, if you were to draw three cards consecutively with replacement, what would be the expected total value of these cards?$bt$\n WHERE id = 'card-expectations-ii' AND updated_by IS NULL AND md5(question) = '4a82a6549918228e64e062491829a7c9' AND md5(answer) = 'f13e4743ccc5cc5cade51a3a383e2b6c';\nUPDATE public.brainteasers SET question = $bt$You're invited to play a coin toss game with unique rules. The game uses a fair coin, and each player scores points based on the coin's outcome: if it lands tails up, you earn a point; if it lands heads up, your opponent scores a point. The game concludes when a player has achieved a two-point lead over their competitor, upon which the losing party must pay the winner one euro.\n\nA twist in the game allows you, at any time before the match ends, to invoke an option to double the final payout. However, this can only be exercised once. Given these rules and the ability to strategically double the payout, what is the maximum amount you would be willing to pay for the privilege of participating in this game?$bt$\n WHERE id = 'coin-game' AND updated_by IS NULL AND md5(question) = '5c21d8346688e0e8610c8445968c4270' AND md5(answer) = 'dd0b9687a605b986e91bbf834e41a891';\nUPDATE public.brainteasers SET answer = $bt$To solve this, we can set up a recurrence relation using E, which stands for the expected number of rolls. At the start, we anticipate an average of 6 rolls for the first 6 to appear. After rolling a 6:\n\nThere's a 1/6 chance that the very next roll will also be a 6.\n\nThere's a 5/6 chance that we will roll a different number, effectively taking us back to the beginning scenario.\n\nFrom these probabilities, we can derive the equation:\n\n$$\nE = 6 + \\left(\\frac{1}{6} \\times 1\\right) + \\left(\\frac{5}{6} \\times (E + 1)\\right)\n$$\n\nSolving for E, we get:\n\n$$\nE = 42\n$$\n\nSo, on average, you need to roll a 6-sided die 42 times until a 6 shows up twice consecutively.$bt$\n WHERE id = 'consecutive-sixes' AND updated_by IS NULL AND md5(question) = 'ea44004358ff14caa1d998ba46423d7b' AND md5(answer) = '64edfabc9700539e404a4e001b6071ca';\nUPDATE public.brainteasers SET question = $bt$Given a point $(X_1, X_2, \\dots, X_{10})$ that is selected uniformly at random from the 10-dimensional ball with radius 12 centered at the origin, find the variance of $X_1$, the first coordinate.$bt$\n WHERE id = 'coordinate-variance' AND updated_by IS NULL AND md5(question) = '65f18e328dc8f2cc5a882ef178a92e3c' AND md5(answer) = 'ffed720afa39429a425e0a22530b6851';\nUPDATE public.brainteasers SET answer = $bt$To deduce Alice's winning odds, consider the following steps:\n\nIndividual Probabilities:\n\nAlice's chance of getting a sum of 6 with two dice is 5/36, achieved with combinations: 1&5, 5&1, 2&4, 4&2, 3&3.\n\nBob's chance of getting a sum of 7 with two dice is 6/36 or 1/6, achieved with combinations: 1&6, 6&1, 2&5, 5&2, 3&4, 4&3.\n\nFirst-Roll Advantage:\n\nWhile Bob has a slightly better probability of hitting his target sum, Alice has the initial roll advantage.\n\nGame Modeling:\n\nPicture the game as a sequence where both Alice and Bob repeatedly miss their sums until Alice finally achieves a 6. This can be described using a geometric distribution. Alice's winning probability is:\n\n$$\n\\sum_{k=0}^{\\infty} (1-p)^k (1-r)^k\\, p = \\frac{p}{1-(1-p)(1-r)}\n$$\n\nwhere $p$ represents Alice's odds of getting a 6 and $r$ represents Bob's odds of getting a 7.\n\nUsing the probabilities provided, Alice's winning chance is roughly 30/61 or about 0.49, meaning Bob has a slight edge even though Alice rolls first.$bt$\n WHERE id = 'dice-game' AND updated_by IS NULL AND md5(question) = 'cf05b2aa34187c3548531c3396c667f2' AND md5(answer) = 'a1b6c6afc472a854e6572a8513b464eb';\nUPDATE public.brainteasers SET question = $bt$After the previous dice game, you are often asked to play a market making game on call option where the expected payoff the value of dice 1 raised to the power of dice 2 ($D_1^{\\,D_2}$) and you have a call option with a strike price of 30.$bt$, answer = $bt$Note that you should immediately realize that the highest payout for the option is $6^6 - 30 = 46{,}626$, which can occur with probability 1/36. This already puts the expected payoff off the game over \\$1200 to give you an idea of the order of magnitude that we are dealing with in this game. It's not so much about calculating things exactly right. It's more about having a feel for the order of magnitude of the payoff of the game and how you deal with these kinds of situations.$bt$\n WHERE id = 'dice-option-game-ii' AND updated_by IS NULL AND md5(question) = '21d5f1d978f2549a1ed1147d242f0801' AND md5(answer) = '8725a153086b497288b11752e1db7261';\nUPDATE public.brainteasers SET answer = $bt$First, determine the value of the share as a portion of the ETF:\n\n5% of 50 = 0.05 \u00d7 50 = 2.5.\n\nThis means the share (when it was valued at 75) was contributing 2.5 to the ETF's value.\n\nNext, find out how much the ETF increased due to the rise in the share price:\n\nSince the share price increased from 75 to 100, the increase is 100 - 75 = 25.\n\nGiven that the share contributes 2.5 to the ETF's value when it's priced at 75, for every unit increase in the share's price, the ETF's value increases by 2.5/75.\n\nTherefore, the ETF's value increases by (2.5/75) \u00d7 25 = 0.8333.\n\nFinally, to find the new value of the ETF:\n\n50 (original ETF value) + 0.8333 = 50.8333.\n\nSo, the new value of the ETF is 50.8333.$bt$\n WHERE id = 'etf-pricing-i' AND updated_by IS NULL AND md5(question) = '06cdf21a9f0629d5ca06249defa7535d' AND md5(answer) = 'bea2141e716439c4262ac6b598b52494';\nUPDATE public.brainteasers SET question = $bt$You are playing a card game with a standard 52-card deck where the values of the cards are as follows: $\\text{Ace} = 1$, $2$ through $10$ are their respective numbers, $\\text{Jack} = 11$, $\\text{Queen} = 12$, and $\\text{King} = 13$.\n\nYou draw $3$ cards at random. From these $3$ cards you reveal the smallest card and set it aside. From the remaining $2$ cards, you draw $1$.\n\nWhat is the expected value of the card you draw next?$bt$\n WHERE id = 'expected-values-of-cards' AND updated_by IS NULL AND md5(question) = '93ef4f8e0e60001884b3dfd67573721e' AND md5(answer) = 'd823cee84c9ef8192c4802a2fbad7782';\nUPDATE public.brainteasers SET answer = $bt$Population of New York City: New York City had a population of approximately 8.4 million people as of the last known data.\n\nHouseholds with pianos: Let's assume that 1 out of every 100 households owns a piano. Given an average of 2.5 people per household, there are roughly 3.36 million households in NYC. Therefore, there might be about 33,600 pianos in New York City.\n\nFrequency of tuning: While a piano typically needs tuning once a year, not all piano owners might adhere to this. Let's assume only 50% of the pianos get tuned annually. This brings our count down to 16,800 pianos being tuned every year.\n\nPiano tuners' workload: If one piano tuner can tune 3 pianos a day, and they work 5 days a week, they can tune approximately 780 pianos a year (3 pianos/day \u00d7 5 days/week \u00d7 52 weeks/year).\n\nNumber of piano tuners: To determine the number of piano tuners in NYC, divide the total number of tunings needed by the number of tunings one tuner can handle in a year: 16,800 / 780 = 21.54. Accounting for part-time tuners, vacation days, and potential tuning of pianos from outside the households (like schools, churches, and concert venues), let's factor this in and say there are approximately 40 piano tuners in NYC.\n\nRemember, the aim of Fermi questions is not just to hone your estimation and logical reasoning skills but also to test your numerical skills, ensuring you can handle calculations accurately and efficiently.$bt$\n WHERE id = 'fermi-piano-tuners' AND updated_by IS NULL AND md5(question) = '884f707859cb1f00a6c2d9d974ad6ec1' AND md5(answer) = 'a4282950e6644f335783e1ab5c32e9e7';\nUPDATE public.brainteasers SET answer = $bt$General Approach to Fermi Questions:\n\nBreak Down the Problem: Start by decomposing the problem into smaller, more manageable parts.\n\nEstimate: For Fermi problems, precision isn't the goal. Use rounded numbers and general knowledge to make estimates.\n\nSimplify: Use general knowledge and logic to simplify complex elements of the question.\n\nCalculate: Once you have all your estimates, perform the calculations. This is where your numerical skills come into play. Always double-check your math.\n\nRefine: Consider factors you might have missed in your initial estimate and adjust your answer accordingly.\n\nPractice: The more Fermi problems you tackle, the sharper your estimation, reasoning, and numerical skills will become.\n\nRemember, the aim of Fermi questions is not just to hone your estimation and logical reasoning skills but also to test your numerical skills, ensuring you can handle calculations accurately and efficiently.\n\nNow, on to this specific example:\n\nVolume of a tennis ball: A tennis ball has a diameter of about 6.7 cm. Its volume can be calculated using the formula for the volume of a sphere: $V = \\frac{4}{3}\\pi r^3$. Using a radius of 3.35 cm (half of 6.7 cm), the volume is roughly 157.48 cm\u00b3 or 0.00015748 m\u00b3.\n\nVolume of a school bus: A typical school bus might be around 12 m long, 2.5 m wide, and 3 m high. So its volume can be roughly estimated as: 90 m\u00b3.\n\nNumber of tennis balls: To determine how many tennis balls can fit, divide the volume of the bus by the volume of a tennis ball: 90 / 0.00015748 = approximately 571,429. To account for the inefficiencies in packing spheres, reduce this by about 10-15% (as not every bit of space will be used due to the gaps between balls). This gives roughly 500,000 tennis balls.$bt$\n WHERE id = 'fermi-tennis-balls' AND updated_by IS NULL AND md5(question) = 'cf1454867f7909bfdf68a51815f45006' AND md5(answer) = '9a1a67bb3edf7e97ba45221a47025c3c';\nUPDATE public.brainteasers SET answer = $bt$The first step in solving this problem is observing that the first outcome is irrelevant to the solution, and recognizing the remainder as a classic example of a symmetric gambler's ruin problem.\n\nIn the classical gambler\u2019s ruin problem, when there is an equal chance of moving up or down (i.e., each step has probability $\\frac{1}{2}$), one can derive a simple closed-form expression for the probability of reaching $0$ before reaching $N$. Suppose the initial position lies at $i$, where $0 < i < N$. In that case, the probability of hitting $0$ first is given by\n\n$$\nf_i \\;=\\;\\frac{\\,N - i\\,}{\\,N\\,}.\n$$\n\nEquivalently, the probability of hitting $N$ before $0$ is $i / N$. For completeness, let's quickly show why this must be the case.\n\nConsider a random walk on the integers from $0$ to $N$, with equal probabilities ($\\frac{1}{2}$) of moving left or right, and with $0$ and $N$ serving as absorbing boundaries. Suppose you start at position $i$, where $1 \\le i \\le N-1$.\n\nLet $f_i$ be the probability of eventually hitting $0$ starting from $i$. By definition, hitting $N$ occurs with probability $\\,1 - f_i$. Since the walk is fair, its expected final position should be exactly $i$, the initial position. But the final position can only be $0$ or $N$. Hence, if the random walk ends up at $0$ with probability $f_i$ and at $N$ with probability $\\,1 - f_i$, the expected final position is\n\n$$\n0 \\times f_i \\;+\\; N \\times (1 - f_i)\\;=\\; N \\,\\bigl(1 - f_i\\bigr).\n$$\n\nBecause the expected final position must equal the initial position $i$, we set\n\n$$\ni \\;=\\; N\\,\\bigl(1 - f_i\\bigr).\n$$\n\nRearranging this equation gives\n\n$$\nf_i \\;=\\;\\frac{\\,N - i\\,}{\\,N\\,}.\n$$\n\nConsequently, the probability of reaching $N$ (instead of $0$) starting from $i$ is $\\,1 - f_i = i / N$. Filling in the formula yields a $\\frac{2}{5}$ probability of Harry defeating Fluffy.$bt$\n WHERE id = 'fighting-fluffy' AND updated_by IS NULL AND md5(question) = '9bda217070bb68dfd55ec2ee177aafb6' AND md5(answer) = '1eaa545be3d379fbae69c62cef7cac14';\nUPDATE public.brainteasers SET answer = $bt$To determine if there's an arbitrage opportunity, first find out the future value of both bonds at the end of 5 years.\n\nFor Bond A:\n\nUsing the formula for compound interest, the future value (FV) is calculated as:\n\n$$\nFV = PV\\,(1 + r)^n\n$$\n\nWhere:\n\nPV = Present Value (initial price of the bond)\n\nr = Rate (YTM)\n\nn = Number of years\n\nGiven:\n\nPV = \\$1,000\n\nr = 4%\n\nn = 5\n\nCalculating for Bond A:\n\n$$\n\\begin{aligned} FV_A &= \\$1{,}000\\,(1 + 0.04)^5 \\\\ &= \\$1{,}000\\,(1.21665) \\\\ &= \\$1{,}216.65 \\end{aligned}\n$$\n\nFor Bond B:\n\nSince it's a zero-coupon bond, its future value is its face value. Using the formula:\n\n$$\nFV = PV\\,(1 + r)^n\n$$\n\nGiven:\n\nPV = \\$850\n\nr = 3.5%\n\nn = 5\n\nCalculating for Bond B:\n\n$$\n\\begin{aligned} FV_B &= \\$850\\,(1 + 0.035)^5 \\\\ &= \\$850\\,(1.18769) \\\\ &= \\$1{,}009.54 \\end{aligned}\n$$\n\nComparing the two bonds, Bond A is undervalued compared to Bond B based on their future values.\n\nTo exploit the arbitrage:\n\nBuy Bond A for \\$1,000.\n\nShort sell Bond B, receiving \\$850.\n\nAt the end of 5 years:\n\nYou receive \\$1,216.65 from Bond A.\n\nYou owe \\$1,009.54 for Bond B.\n\nYour profit is \\$1,216.65 - \\$1,009.54 = \\$207.11. Subtracting the initial investment difference of \\$150 (\\$1,000 - \\$850), your net arbitrage profit is \\$57.11.$bt$\n WHERE id = 'fixed-income-arbitrage' AND updated_by IS NULL AND md5(question) = '7db690996c74fbbef19017f0324a6b06' AND md5(answer) = 'd9b9a65fd8786fa784d1eb46ea340e83';\nUPDATE public.brainteasers SET answer = $bt$To solve this, we need to consider the different scenarios in which both people can have the same number of heads.\n\nBoth get 0 heads:\n\nThis means the first person gets 4 tails and the second person also gets 4 tails. The probability of a person getting 4 tails is $\\left(\\frac{1}{2}\\right)^4 = \\frac{1}{16}$. So, the probability of both getting 4 tails is $\\frac{1}{16} \\times \\frac{1}{16} = \\frac{1}{256}$.\n\nBoth get 1 head:\n\nThe probability of a person getting exactly 1 head in 4 flips is $\\binom{4}{1}\\left(\\frac{1}{2}\\right)^4 = \\frac{4}{16} = \\frac{1}{4}$. The probability of both getting 1 head is $\\frac{1}{4} \\times \\frac{1}{4} = \\frac{1}{16}$.\n\nBoth get 2 heads:\n\nThe probability of a person getting exactly 2 heads in 4 flips is $\\binom{4}{2}\\left(\\frac{1}{2}\\right)^4 = \\frac{6}{16} = \\frac{3}{8}$. The probability of both getting 2 heads is $\\frac{3}{8} \\times \\frac{3}{8} = \\frac{9}{64}$.\n\nBoth get 3 heads:\n\nThis is similar to both getting 1 head, since there are 4 ways to choose which flip was tails. The probability for a person to get 3 heads is $\\binom{4}{3}\\left(\\frac{1}{2}\\right)^4 = \\frac{4}{16} = \\frac{1}{4}$. The probability of both getting 3 heads is $\\frac{1}{4} \\times \\frac{1}{4} = \\frac{1}{16}$.\n\nBoth get 4 heads:\n\nThis is similar to both getting 0 heads. The probability of a person getting 4 heads is $\\left(\\frac{1}{2}\\right)^4 = \\frac{1}{16}$. So, the probability of both getting 4 heads is $\\frac{1}{16} \\times \\frac{1}{16} = \\frac{1}{256}$.\n\nNow, we sum up the probabilities of all these scenarios:\n\n$$\n\\begin{aligned} &\\frac{1}{256} + \\frac{1}{16} + \\frac{9}{64} + \\frac{1}{16} + \\frac{1}{256} \\\\ &= \\frac{2}{256} + \\frac{2}{16} + \\frac{9}{64} = \\frac{1}{128} + \\frac{1}{8} + \\frac{9}{64} \\\\ &= \\frac{1}{128} + \\frac{8}{64} + \\frac{9}{64} = \\frac{1}{128} + \\frac{17}{64}. \\end{aligned}\n$$\n\nTo sum fractions, you need to get a common denominator:\n\n$\\frac{1}{128}$ is the same as $\\frac{0.5}{64}$, so:\n\n$$\n\\frac{0.5}{64} + \\frac{17}{64} = \\frac{17.5}{64} = \\frac{35}{128}.\n$$\n\nSo, the probability that both people have the same number of heads after 4 flips each is $\\frac{35}{128}$.$bt$\n WHERE id = 'flipping-coins-again' AND updated_by IS NULL AND md5(question) = '966f3e712224d68dc14b9e0c5873eb59' AND md5(answer) = '51d088c21ec658c31cd99452ec26928f';\nUPDATE public.brainteasers SET question = $bt$You are presented with the choice of two games involving fair standard 6-sided dice. Decide which game offers you a higher likelihood of victory.\n\nGame 1: You are given 4 rolls of a single die, and you need to roll a 6 at least once.\n\nGame 2: You are allowed 24 rolls of two dice together, and you need to get a pair of 6s (i.e., 6 on both dice) at least once.\n\nWhich game gives you a better chance of winning?$bt$\n WHERE id = 'game-choice' AND updated_by IS NULL AND md5(question) = 'a301d50290c4d417e8b010f541b4a240' AND md5(answer) = '070b194a4580136214172b109d5d4aa1';\nUPDATE public.brainteasers SET answer = $bt$In order to calculate the average speed over the entire trip, we need to know the total distance covered and the total time spent.\n\nLet's assume that the distance to the coffee shop is d kilometers. Then the distance of the round trip would be 2d kilometers.\n\nThe time spent going to the coffee shop (at 6 km/h) would be d/6 hours, and the time spent returning (at 4 km/h) would be d/4 hours.\n\nTherefore, the total time for the round trip would be d/6 + d/4 hours. We can simplify this by finding a common denominator:\n\n$\\frac{d}{6} + \\frac{d}{4} = \\frac{2d + 3d}{12} = \\frac{5d}{12}$ hours.\n\nThe average speed is defined as total distance divided by total time. So in this case, it would be:\n\n$\\frac{2d}{5d/12} = \\frac{2d \\times 12}{5d} = \\frac{24}{5}\\ \\text{km/h} = 4.8\\ \\text{km/h}$.\n\nSo, your average speed over the entirety of the trip will be 4.8 km/h.$bt$\n WHERE id = 'going-for-a-coffee' AND updated_by IS NULL AND md5(question) = 'b5e1a208ecdd4e95902d1ac21212187c' AND md5(answer) = 'f49a6281a50619ea1ce64ebe0475251e';\nUPDATE public.brainteasers SET answer = $bt$To solve this, we consider the sequences where exactly 3 consecutive heads (HHH) appear in 5 coin flips. The sequences are in one of these forms: HHH--, --HHH, or -HHH-.\n\n1. HHH--: The first three flips are heads. The last two flips can be anything. The first dash cannot be a head to prevent a longer sequence of heads. The second dash can be anything. This gives 2 options (TH or TT).\n\n2. --HHH: Similar to the first form, but the sequence of heads is at the end. The first dash must be a tail, and the second dash can be anything. This also gives 2 options (HT or TT).\n\n3. -HHH-: Here, the sequence of heads is surrounded by the dashes. Both dashes must be tails, as having a head in either position would extend the sequence of heads. This results in 1 possibility (THT).\n\nAltogether, there are 5 sequences (2 from HHH--, 2 from --HHH, and 1 from -HHH-) out of 32 possible sequences (since $2^5 = 32$ for 5 coin flips). Therefore, the probability is 5/32.$bt$\n WHERE id = 'head-sequence' AND updated_by IS NULL AND md5(question) = '493d46c1ba7df342af84ba45d35b6b3d' AND md5(answer) = '3d2080cdd72d83c0288f49ea1a77c414';\nUPDATE public.brainteasers SET question = $bt$In a game of cards, 8 cards are dealt out from a standard deck. What is the variance of the number of hearts among these 8 cards?$bt$\n WHERE id = 'heartfelt-variance' AND updated_by IS NULL AND md5(question) = 'c9ffb397f062f6cb00c0cfc367907a72' AND md5(answer) = '5e25e5670b0843f9fd1053949865ad74';\nUPDATE public.brainteasers SET question = $bt$Tyson Fury and Francis Ngannou are competing in a unique game where Tyson has a 60% chance of winning each round against Francis. The rules of the game dictate that to win the entire game, one of the players must win $N$ more rounds than the other, and the game continues until one of them achieves this. What is the probability that Tyson Fury wins the entire game as $N$ approaches infinity?$bt$\n WHERE id = 'heavyweights-game' AND updated_by IS NULL AND md5(question) = '8f09a93ff5fd16c8680b6b3b14a77595' AND md5(answer) = '1f7e5e013cab8df807e6226a2fe67ddf';\nUPDATE public.brainteasers SET question = $bt$How do your friends describe you?$bt$\n WHERE id = 'how-do-your-friends-describe-you' AND updated_by IS NULL AND md5(question) = 'd41d8cd98f00b204e9800998ecf8427e' AND md5(answer) = 'ae9ded61a338687b17c1f9d2bc9834dd';\nUPDATE public.brainteasers SET question = $bt$A rope that is one meter long is divided into three segments by two random points. What is the expected length of the longest segment?$bt$\n WHERE id = 'long-rope' AND updated_by IS NULL AND md5(question) = '0d1649389128672f43a4f08c32229d6a' AND md5(answer) = '92831cfa251b328efc1753f4971cec9f';\nUPDATE public.brainteasers SET question = $bt$Calculate the probability that a number $x^3$, where $x$ is an integer between 1 and 10,000, is a magical number. A magical number is defined as one that ends with the digits 11.$bt$\n WHERE id = 'magical-numbers' AND updated_by IS NULL AND md5(question) = '56cd87aefc60b04127102ba22f289a57' AND md5(answer) = 'bab8ab98fc44ea3864a4c53fc59d9885';\nUPDATE public.brainteasers SET answer = $bt$To maximize the probability of picking a black marble, you should divide the marbles as follows:\n\nBowl 1: Put one black marble.\n\nBowl 2: Put the remaining 9 black marbles and all 10 white marbles.\n\nThis way, if you pick Bowl 1, you have a 100% chance of picking a black marble. If you pick Bowl 2, you have a 9 out of 19 chance of picking a black marble, which is less than 50%, but the overall probability will be maximized this way.\n\nHere's the math:\n\nYou have a 1/2 chance of picking either bowl. So, the total probability P(B) of picking a black marble is the sum of the probabilities of picking a black marble from Bowl 1 and Bowl 2, each multiplied by the probability of picking that bowl:\n\n$$\n\\begin{aligned} P(B) &= P(B \\mid \\text{Bowl 1})\\,P(\\text{Bowl 1}) \\\\ &\\quad + P(B \\mid \\text{Bowl 2})\\,P(\\text{Bowl 2}) \\\\ &= 1 \\times \\tfrac{1}{2} + \\tfrac{9}{19} \\times \\tfrac{1}{2} \\\\ &= \\tfrac{1}{2} + \\tfrac{9}{38} = \\tfrac{19}{38} + \\tfrac{9}{38} = \\tfrac{28}{38} = \\tfrac{14}{19} \\end{aligned}\n$$\n\nSo, the probability of picking a black marble is 14 out of 19, or approximately 73.68%.$bt$\n WHERE id = 'marbles-ii' AND updated_by IS NULL AND md5(question) = 'f5043131d4b6184fd8f45e750fedb0b8' AND md5(answer) = '850e81ca79c5bfe376dfe902047b8b07';\nUPDATE public.brainteasers SET answer = $bt$In this contest, each chef has an equal chance of securing any position, as they are all equally skilled. The probability of any chef finishing in a specific position is 1/6. Therefore, the likelihood of Chef 2 securing the second spot is 1/6. Once Chef 2 is in second place, there are two remaining positions in the top three for Chef 5 to occupy. However, with Chef 2 occupying one spot, only 5 positions are left for Chef 5. So, the probability of Chef 5 being in the top three, given Chef 2's position, is 2/5. The combined probability of both events occurring is $\\frac{1}{6} \\times \\frac{2}{5}$, which simplifies to $\\frac{1}{15}$.$bt$\n WHERE id = 'masterchef' AND updated_by IS NULL AND md5(question) = '932940fea71415102712eca6309e49d5' AND md5(answer) = 'acebe31e23937992379cdb56abbc819b';\nUPDATE public.brainteasers SET question = $bt$In a drawer, there are $3$ red socks and $n$ blue socks. We know that when two socks are drawn uniformly at random without replacement, the probability that both socks are red is $\\frac{1}{2}$. Can you find the value of $n$?$bt$\n WHERE id = 'matching-socks' AND updated_by IS NULL AND md5(question) = 'ce070a9c7fb1c54c1b79959bfdb41adc' AND md5(answer) = 'fb8bcc7460fa5f7cf237284eabfa6125';\nUPDATE public.brainteasers SET question = $bt$Eighteen boys are standing around in a circle, one of whom is named Benjamin. Twelve girls approach and join the circle at random to form a larger circle. Each girl must stand between two boys. Assuming that the girls arrange themselves in such a way that all possibilities for forming a larger circle are equally likely, calculate the probability that Benjamin is still standing between two boys.$bt$\n WHERE id = 'more-boys-and-girls' AND updated_by IS NULL AND md5(question) = '9392167951a71fa833e4e01f17e3c5a1' AND md5(answer) = '2d4b28f4dfe7fc19ea2e1fab0b207a6f';\nUPDATE public.brainteasers SET question = $bt$You have two envelopes in front of you. Each envelope has an equal chance of containing either a blue or red card inside. You already know one of these envelopes holds a red card.\n\nWhat is the probability that the other envelope also contains a red card?\n\nHow does this change if you are told the first envelope you picked contains a red card?$bt$\n WHERE id = 'opening-envelopes' AND updated_by IS NULL AND md5(question) = '9e080000fa89e5377115f8097215ae29' AND md5(answer) = '36ac23057f9ef76f22f6eedd30751145';\nUPDATE public.brainteasers SET answer = $bt$To find the solution, imagine unfolding the cube onto a flat 2D surface. When this is done, the path from Pikachu's starting corner to its destination becomes a straight diagonal across a rectangle formed by two adjacent faces of the cube. This rectangle's dimensions are 1 unit by 2 units. This diagonal route is the hypotenuse of a right triangle with sides of lengths 1 and 2. By applying the Pythagorean theorem, we can deduce that the hypotenuse (Pikachu's shortest path) is $\\sqrt{1^2 + 2^2}$, which results in $\\sqrt{5}$.$bt$\n WHERE id = 'pikachu-s-box' AND updated_by IS NULL AND md5(question) = '68fe05d8c99b0bf67ec284c97a40418c' AND md5(answer) = '7070a8e2c03f101f752c7b7a1222a99c';\nUPDATE public.brainteasers SET question = $bt$Suppose we have a random variable $X$ which follows a Poisson distribution with parameter $\\lambda$, denoted as $X \\sim \\text{Pois}(\\lambda)$. Additionally, $\\lambda$ itself is a random variable that follows an exponential distribution with parameter 1, denoted as $\\lambda \\sim \\text{Exp}(1)$. Compute the expected value of $X$, that is, $\\mathbb{E}[X]$.$bt$\n WHERE id = 'poisson-expectation' AND updated_by IS NULL AND md5(question) = '68eac42459eeb9e27f97e1bff51ebdab' AND md5(answer) = '5abfc71eb5ead9ba566557cc8f683828';\nUPDATE public.brainteasers SET answer = $bt$Let the two ordered draws be $(C_1, C_2)$.\n\n1. P(tie) = $\\Pr(\\text{rank}(C_1)=\\text{rank}(C_2)) = \\frac{3}{51} = \\frac{1}{17}$.\n\n(After any first card, 3 of the 51 remaining match its rank.)\n\n2. By symmetry of the deck, $\\Pr(\\text{rank}(C_1)>\\text{rank}(C_2)) = \\Pr(\\text{rank}(C_1)<\\text{rank}(C_2))$\n\n3. The three mutually exclusive events are \u201cfirst higher\u201d, \u201csecond higher\u201d, and \u201ctie\u201d, so\n\n$$\n2\\,\\Pr(\\text{first higher}) + \\frac{1}{17} = 1\n$$\n\n$$\n\\Pr(\\text{first higher}) = \\frac{1-1/17}{2} = \\frac{8}{17}.\n$$$bt$\n WHERE id = 'rank-before-you-draw' AND updated_by IS NULL AND md5(question) = '9e3b68dcc546f913639903b5836e5c4e' AND md5(answer) = 'e4e56599338b07f2fa339d531969943e';\nUPDATE public.brainteasers SET question = $bt$You are asked to play a game where you roll a fair six-sided die repeatedly, until a number appears that has already been rolled. Let $r$ be the number of times the die was rolled, and $p_r$ be the probability of rolling the die $r$ times.\n\nWhat is the probability $p_3$ that the game ends on the third roll?$bt$, answer = $bt$For r to equal 3, two conditions must be met:\n\nThe first and second rolls must yield different numbers.\n\nThe third roll must match either the value of the first or second roll.\n\nGiven that each roll is an independent event, we can calculate the probability of each event occurring in succession.\n\nThe probability of the first roll being any value is certain: 6/6.\n\nThe probability that the second roll is different from the first is 5/6 since there are 5 numbers it can be to not match the first roll.\n\nThe probability that the third roll matches either the first or the second roll is 2/6 because there are two numbers it needs to match and four it must not.\n\nTherefore, $p_3 = \\frac{6}{6} \\times \\frac{5}{6} \\times \\frac{2}{6} = \\frac{10}{36}$.$bt$\n WHERE id = 'repeated-rolls' AND updated_by IS NULL AND md5(question) = 'b53bbb485ec746825e6e3e1a7e37e64c' AND md5(answer) = '476c8e04eee9b3fce97f32947fe1cbb6';\nUPDATE public.brainteasers SET question = $bt$Suppose you roll a fair 6-sided die until you either obtain a 2 for the first time or 2 consecutive 1s. What is the expected number of rolls you perform?$bt$\n WHERE id = 'rolling-1s-and-2s' AND updated_by IS NULL AND md5(question) = 'adb50fa48992489760a511aaf5bb7a74' AND md5(answer) = '3f2ffa2417d5f6eed2930ba424710c4f';\nUPDATE public.brainteasers SET answer = $bt$If we assume constant speeds for all participants, then the relative distances between the racers would be proportional to their relative speeds.\n\nHere's how you can think of it:\n\nWhen Bolt finishes the race (100m), Kipchoge has run 80m (100m - 20m). This means Bolt runs 1.25 times faster than Kipchoge (100m/80m = 1.25).\n\nSimilarly, when Kipchoge finishes his 100m race, Diniz has only run 80m. So, Kipchoge runs 1.25 times faster than Diniz.\n\nBecause speed is transitive (if A is faster than B, and B is faster than C, then A is faster than C), Bolt is thus 1.25 \u00d7 1.25 = 1.5625 times faster than Diniz.\n\nSo, when Bolt finishes his 100m race, Diniz has only run 100m / 1.5625 = approximately 64m.\n\nTherefore, Bolt beats Diniz by approximately 36m (100m - 64m).$bt$\n WHERE id = 'running' AND updated_by IS NULL AND md5(question) = '78a590a7d37416edd04c40d1ddc7d8c0' AND md5(answer) = '153fdb307a00073bda232678f23c709d';\nUPDATE public.brainteasers SET question = $bt$Consider a dataset where each observation is normally distributed with a mean (\u03bc) of 50 and a standard deviation (\u03c3) of 5. If you randomly select a sample of size n, what is the probability that the sample mean is greater than 55?$bt$\n WHERE id = 'sampling-surprise' AND updated_by IS NULL AND md5(question) = 'a65c9d7c9981adbe21cdaa6320eb0456' AND md5(answer) = '70eecd09e646c69010d263eebc8cb14c';\nUPDATE public.brainteasers SET question = $bt$Suppose that $X$ and $Y$ are independent standard normal random variables. What is the probability $P[Y > 4X]$?$bt$\n WHERE id = 'standard-normal' AND updated_by IS NULL AND md5(question) = '1b9ec39a2a2ce8e162c5f62299c31bd9' AND md5(answer) = '70ad0fbcfd25a45839ba087a579ce70c';\nUPDATE public.brainteasers SET answer = $bt$Consider the problem of transporting $3{,}000$ gallons of oil over a $1{,}000$-mile distance, with the loss of $1$ gallon per mile regardless of load, and a truck capacity limited to $1{,}000$ gallons. To maximize the amount delivered to City B, it is optimal to use intermediate depots to reduce the effective per-mile loss by decreasing the number of trips required as the journey progresses.\n\nStage 1 ($0$ to $d_1$ miles):\n\nStarting with $3{,}000$ gallons at City A, the truck must make 3 forward trips to move the oil and 2 return trips to pick up additional oil, resulting in an effective cost of 5 gallons per mile. To reduce the oil inventory from $3{,}000$ to $2{,}000$ gallons (thereby lowering the number of trips needed in subsequent stages), we set up the equation:\n\n$$\n3{,}000 - 5d_1 = 2{,}000\n$$\n\nSolving for $d_1$ gives:\n\n$$\n5d_1 = 1{,}000 \\quad \\Longrightarrow \\quad d_1 = 200 \\text{ miles.}\n$$\n\nThus, a depot is established at 200 miles from City A, where $2{,}000$ gallons are stored.\n\nStage 2 ($d_1$ to $d_1 + d_2$ miles):\n\nWith $2{,}000$ gallons available, only 2 forward trips (and 1 return trip for the first load) are required, so the effective loss is 3 gallons per mile. To further reduce the stock from $2{,}000$ to $1{,}000$ gallons, the equation is:\n\n$$\n2{,}000 - 3d_2 = 1{,}000\n$$\n\nThis yields:\n\n$$\n3d_2 = 1{,}000 \\quad \\Longrightarrow \\quad d_2 = \\frac{1{,}000}{3} \\approx 333.33 \\text{ miles.}\n$$\n\nThe second depot is therefore placed at:\n\n$$\n200 + 333.33 \\approx 533.33 \\text{ miles from City A,}\n$$\n\nstoring $1{,}000$ gallons.\n\nStage 3 ($d_1 + d_2$ to $1{,}000$ miles):\n\nWith only $1{,}000$ gallons left, a single trip suffices, and the loss is simply 1 gallon per mile. The remaining distance is:\n\n$$\n1{,}000 - 533.33 \\approx 466.67 \\text{ miles,}\n$$\n\nresulting in a loss of approximately $466.67$ gallons. Thus, the oil delivered to City B is:\n\n$$\n1{,}000 - 466.67 \\approx 533.33 \\text{ gallons.}\n$$\n\nIn summary, using the optimal depot strategy, approximately $533.33$ gallons of oil can be successfully transported to City B.$bt$\n WHERE id = 'storage-locations' AND updated_by IS NULL AND md5(question) = 'e115e092b4e1cab71dd3e3f5b9a050c4' AND md5(answer) = 'f03adda640e77778576999a8f06e0b5b';\nUPDATE public.brainteasers SET answer = $bt$Given that there are 12 different psychedelic drugs and you want to use exactly 3 different ones at each of four events, this is a problem of combinations without repetition.\n\nFirst, let's calculate how many combinations of 3 different drugs we can make from 12. This is given by the formula for combinations: $\\binom{n}{k} = \\frac{n!}{k!\\,(n-k)!}$, where n is the total number of items (here, 12 drugs), k is the number of items to choose (here, 3 drugs), and \"!\" denotes the factorial operation.\n\nSo, $\\binom{12}{3} = \\frac{12!}{3!\\,(12-3)!} = 220$.\n\nSo, we have 220 different ways to select 3 drugs out of 12 for a single event.\n\nNow, we want to use 3 drugs at each of 4 events, and we want to use each drug exactly once, meaning we can't use the same combination of drugs for multiple events.\n\nSo, we will select 3 drugs for the first event (220 ways to do that), then another 3 drugs from the remaining 9 for the second event, then another 3 drugs from the remaining 6 for the third event, and the final 3 drugs for the last event.\n\nThe number of ways to do this will be $\\binom{12}{3} \\binom{9}{3} \\binom{6}{3} \\binom{3}{3}$.\n\n$\\binom{12}{3} = 220$ (as we calculated before).\n\n$\\binom{9}{3} = \\frac{9!}{3!\\,(9-3)!} = \\frac{9 \\cdot 8 \\cdot 7}{3 \\cdot 2 \\cdot 1} = 84$.\n\n$\\binom{6}{3} = \\frac{6!}{3!\\,(6-3)!} = \\frac{6 \\cdot 5 \\cdot 4}{3 \\cdot 2 \\cdot 1} = 20$.\n\n$\\binom{3}{3} = 1$ (there's only one way to choose 3 things out of 3).\n\nSo the total number of ways to select 3 drugs for each of 4 events, using each drug exactly once, is $220 \\times 84 \\times 20 \\times 1 = 369{,}600$.\n\nRemember: The combination of drugs should be considered carefully due to possible harmful effects and contraindications. This brainteaser is purely mathematical and doesn't advocate or promote the use of psychedelic drugs. Always consult with healthcare professionals for information about drug interactions. The topic of this brainteaser was chosen solely to make sure you don't forget it!$bt$\n WHERE id = 'taking-substances-at-parties' AND updated_by IS NULL AND md5(question) = '6391ee0fecde661df1a8d2884a5cd7bb' AND md5(answer) = '47207e631c2978e77621a553131632df';\nUPDATE public.brainteasers SET question = $bt$Three players act in order. Player 1 first announces an integer between 1 and 100. Player 2 sees Player 1\u2019s choice and then announces his own integer (it must be different, but still between 1 and 100). Player 3 sees both earlier choices and then announces his integer, again different and between 1 and 100.\n\nWhen all three numbers have been fixed, a random integer $R$ is drawn uniformly from 1 to 100. The player whose number is closest to $R$ wins; if two players are equally close, the tie is broken by a fair coin-toss.\n\nAssuming Players 2 and 3 play perfectly rationally (each always picking the move that maximises their eventual probability of winning), what number should Player 1 choose to maximise his own chance of winning?$bt$\n WHERE id = 'the-number-guessing-dilemma' AND updated_by IS NULL AND md5(question) = 'ae9f8a1ce67ad5a7ece79692e0d19de8' AND md5(answer) = '257cb23cf46e37e42cf42e82966b8c8b';\nUPDATE public.brainteasers SET question = $bt$You\u2019re given a stack of $n$ blank cards. On the back of each card, write a number between 1 and 5.\n\nAnother player, after seeing how many of each number you have written (but not which card is which), randomly picks one card, keeps it face-down, and guesses its number. If the named number matches the number on the drawn card you must pay that many dollars (for instance, \\$5 for a 5); otherwise you pay nothing.\n\nHow should you distribute the numbers across the cards so that this fully informed, rational player cannot choose a guess that gives them a higher expected payout than any other?$bt$\n WHERE id = 'the-sneaky-card-game' AND updated_by IS NULL AND md5(question) = 'c74a8b26fad1fba11645b00779fa9447' AND md5(answer) = 'bc7771eca4166c8badc2c0c89740b04e';\nUPDATE public.brainteasers SET question = $bt$In a game where two fair dice are rolled and the resulting score is calculated by multiplying the number on each die, what would be the product of all possible scores that have the maximum chance of being the outcome of this game?$bt$\n WHERE id = 'throwing-dice' AND updated_by IS NULL AND md5(question) = 'dbceedba9a40023b951f2a5d2f7bcefd' AND md5(answer) = 'f0b99aa8e689d0fb03860e3d6d2153cd';\nUPDATE public.brainteasers SET question = $bt$Person A and B play a coin-tossing game. Person A makes a bet of x dollars on either heads or tails. Person B then flips a fair coin. If the outcome matches A's guess, A receives 2x dollars; if not, A loses his bet. Person A has a strategy in mind: He starts by betting 1 dollar (x:=1). If he wins, he continues to bet 1 dollar. If he loses, he triples his previous bet (x:=x*3). It appears that with this strategy, if Person A wins at any point, he will make a profit. This suggests that A will always end up in profit. Is there any flaw or problem with this strategy?$bt$\n WHERE id = 'tossing-game' AND updated_by IS NULL AND md5(question) = '6b69907a87f47feba764b89465b72fe5' AND md5(answer) = 'b058bf90c0eb380cc979b5d2413dde42';\nUPDATE public.brainteasers SET answer = $bt$To determine this probability, we must consider the specific conditions that need to be met for the game to conclude on the $10^\\text{th}$ toss:\n\n1. Tosses 9 and 10 must be $HH$, since that is when the game ends.\n\n2. Tosses 1\u20138 must contain no consecutive heads.\n\n3. Toss 8 must be $T$, otherwise an $H$ at toss 9 would create $HH$ earlier (at 8\u20139).\n\nLet $F_n$ denote the number of valid sequences of length $n$ that contain no consecutive heads and end with $T$.\n\nSuch sequences satisfy the recurrence:\n\n$$\nF_n = F_{n-1} + F_{n-2}, \\quad \\text{with} \\quad F_1 = 1, \\; F_2 = 2.\n$$\n\nThis is a Fibonacci-type relation, and iterating gives $F_8 = 34$.\n\nEach of these 34 valid 8-toss prefixes can be followed by $HH$ at tosses 9 and 10, forming 34 valid 10-toss sequences.\n\nEach 10-toss sequence has probability $(1/2)^{10}$.\n\nHence, the probability of stopping exactly on the 10th toss is:\n\n$$\nP(\\text{stop on toss }10) = 34 \\times (1/2)^{10} = 34/1024 = 17/512.\n$$$bt$\n WHERE id = 'tossing-ten' AND updated_by IS NULL AND md5(question) = 'be74dcd634f39b0dde08f629b354dca7' AND md5(answer) = 'ff0f55e40057cb8b85d12b8aea6e14b7';\nUPDATE public.brainteasers SET question = $bt$A lineup of $100$ traders is ready to execute trades on the stock market. Each trader has a unique order tied to a specific stock ticker. For simplicity, let's say that the $n$-th trader in line has an order for stock ticker $n$.\n\nThe first trader, overwhelmed by market noise and volatility, chooses to execute a trade on a random stock ticker (equally likely for each ticker). All the other traders are well-informed and will execute their trades on their specific stock tickers, unless it's already been traded. If the stock they intended to trade has already been traded, they will then choose another stock ticker to trade on, randomly.\n\nWhat is the probability that the last trader will execute their trade on their designated stock ticker $(\\#100)$?$bt$\n WHERE id = 'trading-places' AND updated_by IS NULL AND md5(question) = '6614de90eaebf5821a3c34449b09b5c0' AND md5(answer) = '4054a4e532d913c502fd6f0e2dd84fed';\nUPDATE public.brainteasers SET answer = $bt$To calculate the probability of both cards being aces when drawn without replacement, we need to determine the probabilities of each event happening and then multiply them together.\n\nThere are 4 aces in a standard deck of 52 cards. When you draw the first card, the probability that it is an ace is:\n\nP(Ace on 1st draw) = (Number of aces) / (Total number of cards)\n\nP(Ace on 1st draw) = 4/52 = 1/13\n\nNow, there are only 51 cards left in the deck, and only 3 aces. The probability that the second card drawn is an ace is:\n\nP(Ace on 2nd draw) = (Number of remaining aces) / (Total number of remaining cards)\n\nP(Ace on 2nd draw) = 3/51 = 1/17\n\nNow, we multiply these probabilities together to find the probability of both cards being aces:\n\nP(Both cards are aces) = P(Ace on 1st draw) \u00d7 P(Ace on 2nd draw)\n\n$P(\\text{both aces}) = \\frac{1}{13} \\times \\frac{1}{17} = \\frac{1}{221}$\n\nSo the probability of drawing two aces without replacement is 1/221.$bt$\n WHERE id = 'two-cards-from-a-deck' AND updated_by IS NULL AND md5(question) = '2c7c602ed32e62bc96df5e85d1ea9088' AND md5(answer) = '7a34e1fa5993a77e3a2006dbd39caa42';\nUPDATE public.brainteasers SET question = $bt$Let $X$ be a continuous random variable with probability density function\n\n$$\nf(x) = \\begin{cases} 1, & 0 \\le x \\le 1 \\\\0, & \\text{otherwise}\\end{cases}\n$$\n\nWhat is the variance of $X$?$bt$\n WHERE id = 'uniform-random-variable' AND updated_by IS NULL AND md5(question) = '51d490c92dc958c61eee17cd530d3d17' AND md5(answer) = '959105bed085988cc77ced1cc76a27da';\nUPDATE public.brainteasers SET question = $bt$Given a random variable $U$ that follows a uniform distribution $U \\sim \\text{Unif}(0,1)$ and a sequence of independent and identically distributed (IID) random variables $X_1, X_2, \\ldots$ also following $X_i \\sim \\text{Unif}(0,1)$, define $N$ as the smallest positive integer such that $X_N > U$. The task is to find the expected value of $N$, denoted as $E[N]$.$bt$\n WHERE id = 'uniform-set' AND updated_by IS NULL AND md5(question) = 'cab70df147e254f8e6af93bb05322a0b' AND md5(answer) = 'e96c0322f1c43cc136c1e076349250aa';\nUPDATE public.brainteasers SET question = $bt$Hodinkee is auctioning a rare vintage Omega watch. They will accept the first bid that is at least \\$9,000. Each bid for the watch is independent and follows an exponential distribution with a mean of \\$5,000. What is the expected number of bids Hodinkee will receive before the watch is sold, including the bid that meets their minimum price? Express your answer in the form $e^a$ for a rational number $a$. Determine the value of $a$.$bt$\n WHERE id = 'watch-auction' AND updated_by IS NULL AND md5(question) = 'a392252df398694764a6e402c11d2637' AND md5(answer) = 'cf86425a41e613aca1da03fb951947b5';\nUPDATE public.brainteasers SET question = $bt$What are your weaknesses?$bt$\n WHERE id = 'what-are-your-weaknesses' AND updated_by IS NULL AND md5(question) = 'd41d8cd98f00b204e9800998ecf8427e' AND md5(answer) = '7fe57be9c66d386ec749243d22ec91ab';\nUPDATE public.brainteasers SET question = $bt$What is the hardest thing you've ever done?$bt$\n WHERE id = 'what-is-the-hardest-thing-you-ve-ever-done' AND updated_by IS NULL AND md5(question) = 'd41d8cd98f00b204e9800998ecf8427e' AND md5(answer) = 'd90b319a20664ca4c0d11bb58dd960f9';\nUPDATE public.brainteasers SET question = $bt$What would be your edge compared to other traders?$bt$\n WHERE id = 'what-would-be-your-edge-compared-to-other-traders' AND updated_by IS NULL AND md5(question) = 'd41d8cd98f00b204e9800998ecf8427e' AND md5(answer) = '3bf69df1ce98120af8c6f1a313ac6533';\nUPDATE public.brainteasers SET question = $bt$What would make you nervous?$bt$\n WHERE id = 'what-would-make-you-nervous' AND updated_by IS NULL AND md5(question) = 'd41d8cd98f00b204e9800998ecf8427e' AND md5(answer) = '4f135ca51c9ff5669cf7c21b2eaa6f14';\nUPDATE public.brainteasers SET question = $bt$Why do you prefer us over our competitors?$bt$\n WHERE id = 'why-do-you-prefer-us-over-our-competitors' AND updated_by IS NULL AND md5(question) = 'd41d8cd98f00b204e9800998ecf8427e' AND md5(answer) = '7a70aedd737250ba4f9b6c799492d1f6';\nUPDATE public.brainteasers SET question = $bt$Why do you want to become a Trader?$bt$\n WHERE id = 'why-do-you-want-to-become-a-trader' AND updated_by IS NULL AND md5(question) = 'd41d8cd98f00b204e9800998ecf8427e' AND md5(answer) = 'e87aaf7cae7f608a96c235527eaa6e2e';\nUPDATE public.brainteasers SET answer = $bt$Let\u2019s denote the volume of the first wine glass as x and the volume of the second wine glass as y. From the given information, we can set up the equation: $\\frac{3}{4}x = \\frac{2}{3}y$. This implies that 3/4 of the first wine glass is equal to 2/3 of the second wine glass. We're asked to solve for the fraction or ratio of the volume of the first wine glass (x) to the volume of the second wine glass (y). This is expressed as x/y. By algebraically manipulating our original equation, we get $\\frac{x}{y} = \\frac{4}{3} \\times \\frac{2}{3} = \\frac{8}{9}$. This means the volume of the first wine glass is 8/9 of the second wine glass. In other words, the second wine glass is larger than the first by 1/8 or 12.5%.$bt$\n WHERE id = 'wine-glasses' AND updated_by IS NULL AND md5(question) = 'a0134ed83fbcce2e366b5c07650eaa40' AND md5(answer) = 'd9193c63b6b826b228af89be51ab6d77';\n"];
